/* Hero: transformación Excel + WhatsApp → Loteo Fácil */
.hero-inner{grid-template-columns:1fr 1.08fr;gap:28px}
.hero-transformation{min-width:0;align-self:center;position:relative}
.transformation-stage{height:410px;position:relative;isolation:isolate;perspective:1050px}
.chaos-scene,.dashboard-scene{position:absolute;inset:0;display:grid;place-items:center;transform-style:preserve-3d}
.chaos-scene{z-index:2;pointer-events:none}
.chaos-sheet{width:76%;position:absolute;background:#fff;border-radius:11px;overflow:hidden;box-shadow:0 24px 50px #071e1b77;border:1px solid #e3e7e2}
.chaos-sheet.sheet-primary{left:0;top:58px;transform:rotate(-6deg);z-index:2}
.chaos-sheet.sheet-secondary{left:12%;top:16px;width:69%;transform:rotate(8deg);opacity:.96;z-index:1;filter:saturate(.95)}
.mock-window-top{height:37px;background:#edf4ee;display:flex;align-items:center;gap:9px;padding:0 11px;color:#274d3d;font-size:10px;font-weight:700}
.mock-excel-icon{width:23px;height:23px;border-radius:4px;background:#167342;color:white;font-size:13px;display:grid;place-items:center;font-weight:900}.mock-more{margin-left:auto;font-size:17px}
.sheet-letters,.sheet-grid{display:grid;grid-template-columns:22px 1.2fr .82fr .83fr .75fr}
.sheet-letters{height:21px;background:#f1f3f1;font-size:9px;color:#718078;text-align:center;align-items:center;border-bottom:1px solid #e5e9e5}
.sheet-cell{border-right:1px solid #e3e8e3;border-bottom:1px solid #e3e8e3;padding:7px 4px;font-size:9px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;color:#4e5b54;min-height:28px}
.sheet-cell.row-id{background:#f4f6f4;text-align:center;color:#95a099}.sheet-cell.head{font-weight:800;background:#e2efe5;color:#1d5134}.sheet-cell.bad{background:#fee9df;color:#a14d32;font-weight:800}.sheet-cell.warn{background:#fff0bd;color:#a35d0a;font-weight:800}.sheet-cell.muted{background:#f7f3e8;color:#8f6d3f;font-weight:700}
.sheet-tab{display:flex;gap:9px;align-items:center;background:#f7f8f6;height:27px;padding-left:12px;color:#6a786f;font-size:8px}.sheet-tab span:first-child{color:#16673f;font-weight:800;border-bottom:2px solid #18814c;padding:7px 3px}
.chaos-chat{width:58%;position:absolute;right:-3%;top:102px;background:#ecefe9;color:#273a34;border-radius:13px;overflow:visible;box-shadow:0 24px 55px #071b186b;border:5px solid #fff;transform:rotate(6deg);z-index:4}
.chat-head{display:flex;align-items:center;gap:8px;padding:10px;background:#f9faf8;border-radius:8px 8px 0 0;font-size:10px}.chat-logo{background:#26a96b;border-radius:50%;height:28px;width:28px;color:#fff;display:grid;place-items:center;font-size:18px}.chat-head b,.chat-head small{display:block}.chat-head small{font-size:8px;color:#75857b}
.chat-stream{padding:4px 0 2px;min-height:180px}
.chat-msg{position:relative;background:#d9f5df;max-width:88%;padding:8px 9px 14px;margin:7px 8px 7px auto;border-radius:8px 8px 2px 8px;font-size:9px;line-height:1.25;box-shadow:0 1px 2px #0000000d;opacity:0;transform:translateY(8px) scale(.97)}.chat-msg.incoming{background:white;margin-left:8px;margin-right:auto;border-radius:8px 8px 8px 2px}.chat-msg small{position:absolute;right:7px;bottom:2px;font-size:7px;color:#6c8575}.chat-input{height:28px;background:white;color:#9ba69d;font-size:9px;padding:7px 10px;display:flex;justify-content:space-between;border-radius:0 0 8px 8px}.chat-input span{color:#289969}
.notification{position:absolute;right:-8px;background:#e84e4e;color:white;border-radius:99px;padding:5px 10px;font-size:9px;font-weight:800;box-shadow:0 6px 12px #0004;opacity:0;transform:scale(.8)}.n-one{top:-18px}.n-two{bottom:-20px;right:20%}
.converge-mark{position:absolute;left:50%;top:45%;z-index:5;display:flex;flex-direction:column;align-items:center;gap:8px;white-space:nowrap;color:white;text-shadow:0 2px 10px #12362a;transform:translate(-50%,-50%) scale(.6);opacity:0;pointer-events:none}.converge-mark span{width:51px;height:51px;border-radius:50%;background:#effaf0;color:#17683f;display:grid;place-items:center;font-size:30px;box-shadow:0 8px 30px #081f1d8a}.converge-mark b{font-size:16px}
.dashboard-scene{z-index:3;opacity:0;transform:scale(.76) translateY(40px);pointer-events:none}.dashboard-scene .browser{transform:none;width:100%;box-shadow:0 28px 72px #071f1cbb;border-width:6px}.dashboard-scene .app{min-height:315px}
.transformation-caption{display:flex;align-items:center;gap:10px;max-width:540px;margin:5px auto 0;color:#f6fff4;font-size:11px;line-height:1.4;text-shadow:0 1px 5px #071b18}.caption-dot{width:7px;height:7px;background:#b5eeb9;border-radius:50%;box-shadow:0 0 0 4px #ffffff24;flex:0 0 auto}.replay-animation{margin-left:auto;flex:0 0 auto;background:#ffffff1a;border:1px solid #ffffff8a;border-radius:5px;color:white;padding:6px 10px;font-size:11px;display:inline-flex;gap:5px;align-items:center}.replay-animation:hover{background:#ffffff36}.replay-animation:focus-visible{outline:3px solid #fff;outline-offset:3px}
